INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var alliancesystemet foer Forste Verdenskrig?","options":["En raekke aftaler der betod at hvis et land blev angrebet maatte dets allierede hjaelpe det","En handelsaftale der hjalp lande med at saelge varer til hinanden","En fredsaftale der garanterede at Europa aldrig ville have krig igen","Et system hvor lande maatte spoerge en domstol foer de aabnede krig"],"correct":"En raekke aftaler der betod at hvis et land blev angrebet maatte dets allierede hjaelpe det","accepted_answers":["En raekke aftaler der betod at hvis et land blev angrebet maatte dets allierede hjaelpe det"],"review_text":"Europa var delt i to store alliancer. Triple Entente: Frankrig, Rusland og England. Triple Alliance: Germany, Oestrig-Ungarn og Italien. Hvis et land gik i krig ville alle dets allierede automatisk goere det samme."}'::jsonb,
  'mc','short','{"concepts":["alliancer","Triple Entente","Triple Alliance","automatisk krig"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvem blev myrdet i Sarajevo i 1914 og udloeste dermed Forste Verdenskrig?","options":["Den ostrigsk-ungarnske aartehertug Franz Ferdinand","Kejser Wilhelm II af Germany","Tsar Nikolaj II af Rusland","Kong George V af England"],"correct":"Den ostrigsk-ungarnske aartehertug Franz Ferdinand","accepted_answers":["Den ostrigsk-ungarnske aartehertug Franz Ferdinand"],"review_text":"Den 28. juni 1914 blev den ostrigsk-ungarnske aartehertug Franz Ferdinand skudt i Sarajevo. Gerningsmanden var den serbiske nationalist Gavrilo Princip. Mordet udloeste en kaedereaktion der endte i verdenskrig."}'::jsonb,
  'mc','short','{"concepts":["Franz Ferdinand","Sarajevo","mordet","udbrud"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var skyttegravskrig?","options":["En type krig hvor soldaterne boede og kaempede i lange udgravede groefte","En type krig der foregik paa havet","En krig hvor kavaleri var den vigtigste styrke","En krig der foregik i bjerge og skove"],"correct":"En type krig hvor soldaterne boede og kaempede i lange udgravede groefte","accepted_answers":["En type krig hvor soldaterne boede og kaempede i lange udgravede groefte"],"review_text":"Paa Vestfronten gravede begge sider lange groefte. Soldaterne boede i disse groefte og forsoegte at erobre fjendens stillinger. Imellem de to sider laag ingenmandsland som var ekstremt farligt at krydse."}'::jsonb,
  'mc','short','{"concepts":["skyttegrove","Vestfronten","ingenmandsland","doedvande"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var ny militaer teknologi i Forste Verdenskrig?","options":["Giftgas, maskingevaerer og fly","Nukleare bomber og missiler","Lasservaaben og droner","Svaerd og hestevogne"],"correct":"Giftgas, maskingevaerer og fly","accepted_answers":["Giftgas, maskingevaerer og fly"],"review_text":"Forste Verdenskrig indfoerte ny og frygtelig teknologi. Giftgas drab og skaadede tusindvis. Maskingevaerer kunne skyde hundredvis af kugler i minuttet. Fly blev brugt til rekognoscering og bomninger. Det goerede krigen endnu mere dodelig."}'::jsonb,
  'mc','short','{"concepts":["giftgas","maskingevaer","fly","ny teknologi","dodelig"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var nationalisme i Europas sammenaenhaeng foer Forste Verdenskrig?","options":["En staerk tro paa at ens eget folk og nation fortjente magt og selvraadighed","En politisk bevaegelse der oenskede at afskaffe alle graenser i Europa","En religioes bevaegelse der ville forene alle kristne lande","Et okonomisk system baseret paa international handel"],"correct":"En staerk tro paa at ens eget folk og nation fortjente magt og selvraadighed","accepted_answers":["En staerk tro paa at ens eget folk og nation fortjente magt og selvraadighed"],"review_text":"Nationalisme betod at folk folte staerk tilknytning til deres nation. Det styrkede sammenholdet i mange lande. Men det skabte ogsaa fjendskab og konkurrence mellem nationer og bidrog til krigen."}'::jsonb,
  'mc','short','{"concepts":["nationalisme","nation","identitet","rivalisering"],"misconception_type":"scope_confusion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad skete der med kvinders rolle under Forste Verdenskrig?","options":["Kvinder overtog mange mandsdomineerede jobs da maend var ved fronten","Kvinders rolle aendrede sig slet ikke under krigen","Kvinder fik forbud mod at arbejde for at beskytte dem","Kvinder kaeempede som soldater paa alle fronter"],"correct":"Kvinder overtog mange mandsdomineerede jobs da maend var ved fronten","accepted_answers":["Kvinder overtog mange mandsdomineerede jobs da maend var ved fronten"],"review_text":"Da maendene blev sendt til fronten manglede fabrikker og gaarde arbejdskraft. Kvinder overtog jobs i vaabenfabrikker, transport og sundhedsvaesen. Det aendrede synet paa hvad kvinder kunne og maatte goere."}'::jsonb,
  'mc','short','{"concepts":["kvinder","roller","arbejde","fabrikker","forandring"],"misconception_type":"overgeneralization","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',7,1
);

